import json,html
from pathlib import Path
root=Path(__file__).parent.parent/'output';out=root/'release-workflow-verification'
read=lambda p:json.loads(p.read_text())
roles=read(root/'release-role-ui-verification/results.json');assert roles['status']=='passed'
auth=read(root/'auth-recovery-verification/results.json');invalid=read(root/'auth-recovery-verification/invalid-session.json')
assert auth['status']==invalid['status']=='passed'
preserved=read(root/'ooru-meeting-audit/verification/preservation.json');assert preserved['status']=='passed'
cleanup=read(out/'fixture-cleanup.json');assert cleanup['status']=='completed'
rows=[]
for kind in ['household','individual']:
 for name,expected in [('returned','published'),('rejected','rejected'),('rejected-level2','rejected'),('change-returned','change-approved'),('change-rejected-level1','change-rejected'),('change-rejected-level2','change-rejected')]:
  s=read(out/kind/(name+'.json'));assert expected in s['checks'];rows.append({'type':kind,'branch':name,'result':'passed','checks':s['checks']})
ui=[read(p) for kind in ['household','individual'] for p in (out/kind).glob('*-ui.json')]
assert all(s['status']=='passed' for s in ui)
report={'status':'passed','deployed_image':'nsipa/master-registry:auth-recovery-20261113-a','authentication_checks':len(auth['results'])+len(invalid['results']),'roles':len(roles['roles']),'layout_checks':sum(len(r['checks']) for r in roles['roles']),'workflow_branches':rows,'ui_checks':sum(len(s['checks']) for s in ui),'preservation':preserved,'cleanup':cleanup,'scope':'Fictional intake fixtures were created through native APIs. Decisions, corrections and resubmissions were exercised through the UI at desktop and phone widths. All five roles were audited at 1440, 768, 390 and 360px. This run did not repeat physical Android GPS/offline capture.','recovered_connection_error':'One individual level-2 return committed successfully but a response read encountered a transient upstream connection error. The returned state was verified before continuing; the decision was not repeated.'}
(out/'results.json').write_text(json.dumps(report,indent=2,default=str))
table=''.join('<tr><td>'+html.escape(r['type'].capitalize())+'</td><td>'+html.escape(r['branch'].replace('-',' '))+'</td><td>Passed</td></tr>' for r in rows)
(out/'verification.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Master Registry verification</title><style>body{font:16px/1.6 system-ui;color:#183e35;background:#edf4eb;margin:0;padding:24px}main{max-width:1000px;margin:auto;background:white;padding:clamp(20px,4vw,48px);border-radius:20px}h1{line-height:1.2}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #d8e5db}td:last-child{color:#12603e;font-weight:600}.stats{display:flex;flex-wrap:wrap;gap:16px}.stats p{background:#edf4eb;padding:16px;border-radius:12px}a{color:#145f50}small{color:#53685e}</style><main><p>MASTER BENEFICIARY REGISTRY · 13 NOVEMBER 2026</p><h1>Session recovery fixed and deployed</h1><p>Unauthorized sessions return to sign-in. Temporary sign-in service failures show a working Try again action. Existing 403 and 413 handling is retained.</p><div class="stats"><p><b>5</b> roles verified</p><p><b>537</b> responsive layout checks</p><p><b>12</b> workflow branches</p><p><b>20</b> authentication checks</p></div><h2>Workflow results</h2><table><thead><tr><th>Registry</th><th>Branch</th><th>Result</th></tr></thead><tbody>'''+table+'''</tbody></table><h2>Records preserved</h2><p>The original 615 native rows and 391 approval-history rows passed preservation checks. Totals are restored to 90 households and 219 individuals. Only UUID-tracked fictional fixtures were removed.</p><h2>Test scope</h2><p>'''+html.escape(report['scope'])+'''</p><p><small>'''+html.escape(report['recovered_connection_error'])+'''</small></p><p><a href="results.json">Detailed results</a> · <a href="../auth-recovery-verification/results.json">Authentication checks</a> · <a href="../release-role-ui-verification/results.json">Five-role UI audit</a></p></main></html>''',encoding='utf-8')
print(json.dumps({k:report[k] for k in ['status','roles','layout_checks','authentication_checks','ui_checks']}))
